export const TOKENS_CSS: string = "/*\n  Sleeve design tokens, version 3: the light theme on :root and the dark theme (D-029) on\n  :root[data-theme='dark'] below it. The root layout's boot script sets data-theme before first paint.\n\n  Source: the owner's closeout app (apps/web: globals.css, product.css, marketing.css,\n  tailwind.config.ts, fonts.ts). Every closeout blue became a green step below, and the spend\n  side of the split gained one warm accent, apricot. Neutrals, type, spacing, radii, shadows and\n  motion are closeout's, with the v1 contrast fixes kept. docs/DESIGN.md explains each value and\n  lists the closeout line every blue came from.\n\n  Components use the semantic tokens (--color-*, --gradient-*, --glass-*, --text-*, --space-*).\n  The --palette-* primitives exist only to feed them; nothing outside this file reads one.\n  contrast.mjs in this folder checks every color claim; run `node scripts/contrast-check.mjs`.\n*/\n\n:root {\n  color-scheme: light;\n  /* Native checkboxes, radios and range inputs default to the browser's blue. */\n  accent-color: var(--color-accent);\n\n  /* Green, OKLCH hue 165 to 171. There is no 400 on purpose: from OKLCH lightness 0.60 to 0.85\n     every vivid green sits within CIEDE2000 10 of a reference green (#00C805, #21CE99, #17AD7B),\n     so the light steps stop at 300 and the deep steps start at 500. Gradients cross that band;\n     no solid token sits in it. */\n  --palette-green-50: #edfcf6;\n  --palette-green-100: #d8faeb;\n  --palette-green-200: #b6f7db;\n  --palette-green-300: #8ff3c9;\n  --palette-green-500: #008561;\n  --palette-green-600: #007456;\n  --palette-green-700: #086149;\n  --palette-green-800: #0d4e3c;\n  --palette-green-900: #0c3b2d;\n  --palette-green-950: #08281f;\n\n  /* Apricot, the spend side. OKLCH hue 43 to 68, clear of the danger red and the waiting amber. */\n  --palette-apricot-50: #fff6ed;\n  --palette-apricot-100: #ffecd9;\n  --palette-apricot-200: #ffd8b5;\n  --palette-apricot-300: #ffbe87;\n  --palette-apricot-400: #ffa053;\n  --palette-apricot-500: #cd6c10;\n  --palette-apricot-600: #b1540b;\n  --palette-apricot-700: #94400c;\n  --palette-apricot-800: #74310e;\n  --palette-apricot-900: #57240c;\n\n  /* Surfaces */\n  --color-canvas: #ffffff;\n  --color-surface: #ffffff;\n  --color-surface-muted: #f4f5f7;\n  --color-surface-strong: #ebedf1;\n  --color-shell: #eceef1;\n  --color-shell-raised: rgba(255, 255, 255, 0.7);\n  --color-chrome: rgba(255, 255, 255, 0.94);\n  --color-scrim: rgba(11, 11, 12, 0.4);\n  --color-skeleton: var(--color-surface-strong);\n  --color-selection: var(--palette-green-200);\n\n  /* Borders. border and border-strong are hairlines and dividers. border-control outlines\n     inputs and checkboxes and must reach 3:1 (WCAG 1.4.11); closeout had no such token. */\n  --color-border: #e7e9ee;\n  --color-border-strong: #d4d8e0;\n  --color-border-control: #898d94;\n\n  /* Ink. ink-muted was #8a909c in closeout (3.21:1 on white); darkened to pass 4.5:1 on\n     canvas and surface-muted. Use ink-secondary on surface-strong, the shell and green-100. */\n  --color-ink: #0b0b0c;\n  --color-ink-secondary: #5b6270;\n  --color-ink-muted: #6a6f7b;\n  --color-ink-inverse: #ffffff;\n\n  /* Brand: the black pill. Primary actions and selected states. Never green. */\n  --color-brand: #101114;\n  --color-brand-strong: #000000;\n  --color-on-brand: #ffffff;\n\n  /* Accent: closeout's #3b71f0 family. One deep green does fills, text, links and focus. */\n  --color-accent: var(--palette-green-600);\n  --color-accent-strong: var(--palette-green-700);\n  --color-accent-soft: var(--palette-green-100);\n  --color-accent-border: var(--palette-green-200);\n  --color-accent-text: var(--palette-green-600);\n  --color-on-accent: #ffffff;\n\n  --color-link: var(--palette-green-600);\n  --color-link-hover: var(--palette-green-700);\n  --color-focus: var(--palette-green-600);\n  --color-focus-inverse: #ffffff;\n\n  /* The split. Spend stays USDG and is apricot; equity became Stock Tokens and is green; waiting\n     is the equity share held as USDG, amber and always hatched in graphics so it never reads as\n     spend. Amounts stay ink: the colored mark beside a number names it. */\n  --color-spend: var(--palette-apricot-500);\n  --color-spend-soft: var(--palette-apricot-100);\n  --color-spend-surface: var(--palette-apricot-50);\n  --color-spend-border: var(--palette-apricot-200);\n  --color-spend-text: var(--palette-apricot-700);\n  --color-equity: var(--color-accent);\n  --color-equity-soft: var(--color-accent-soft);\n  --color-equity-surface: var(--palette-green-50);\n  --color-equity-border: var(--palette-green-200);\n  --color-equity-text: var(--color-accent-text);\n  --color-waiting: var(--color-warning);\n  --color-waiting-soft: var(--color-warning-soft);\n  --color-waiting-text: var(--color-warning-text);\n\n  /* Status. Success shares the green scale: closeout's #17a673 failed AA as text (3.12:1) and sits\n     within CIEDE2000 3 of #17AD7B. Amber and red keep closeout's hue; their -text steps are darker\n     so they pass 4.5:1 on their own soft backgrounds. */\n  --color-success: var(--palette-green-600);\n  --color-success-soft: var(--palette-green-100);\n  --color-success-text: var(--palette-green-600);\n  --color-warning: #bc8000;\n  --color-warning-soft: #fcf3e1;\n  --color-warning-text: #946300;\n  --color-danger: #d93b3b;\n  /* Destructive hover darkens. closeout's opacity 0.9 lightened the red under white text. */\n  --color-danger-strong: #ca2b2f;\n  --color-danger-soft: #fdecec;\n  --color-danger-text: #ca2b2f;\n  --color-on-danger: #ffffff;\n  --color-info: var(--palette-green-600);\n  --color-info-soft: var(--palette-green-50);\n  --color-info-text: var(--palette-green-600);\n\n  /* Charts. Waiting is drawn with --pattern-waiting, never as a flat amber mark. */\n  --color-chart-spend: var(--color-spend);\n  --color-chart-equity: var(--color-equity);\n  --color-chart-waiting: var(--color-waiting);\n  --color-chart-grid: var(--color-border);\n  --color-chart-axis: var(--color-ink-muted);\n  /* green-600 at 14 percent, closeout's area opacity */\n  --color-chart-area: rgba(0, 116, 86, 0.14);\n\n  /* Gradients. Text-bearing ones (hero, apricot, feature, accent-deep) are built from opaque\n     stops only, so the check can measure text against every stop. The stage and the step panel\n     carry no text of their own: content sits on white cards or on --glass-deep. */\n  --gradient-hero: linear-gradient(155deg, var(--palette-green-100) 0%, var(--palette-green-200) 55%, var(--palette-green-300) 100%);\n  --gradient-apricot: linear-gradient(155deg, var(--palette-apricot-50) 0%, var(--palette-apricot-100) 55%, var(--palette-apricot-200) 100%);\n  --gradient-feature: linear-gradient(158deg, var(--palette-green-500) 0%, var(--palette-green-600) 60%, var(--palette-green-800) 100%);\n  --gradient-accent-deep: linear-gradient(155deg, var(--palette-green-600) 0%, var(--palette-green-800) 100%);\n  /* The glow is green-600 */\n  --gradient-stage:\n    radial-gradient(120% 90% at 18% 12%, rgba(255, 255, 255, 0.65) 0%, rgba(255, 255, 255, 0) 60%),\n    radial-gradient(110% 85% at 96% 100%, rgba(0, 116, 86, 0.95) 0%, rgba(0, 116, 86, 0.55) 30%, rgba(0, 116, 86, 0) 68%),\n    linear-gradient(158deg, var(--palette-green-100) 0%, var(--palette-green-200) 42%, var(--palette-green-300) 100%);\n  --gradient-step:\n    radial-gradient(90% 55% at 20% 0%, rgba(255, 255, 255, 0.55) 0%, rgba(255, 255, 255, 0) 62%),\n    linear-gradient(175deg, var(--palette-green-200) 0%, var(--palette-green-300) 28%, var(--palette-green-500) 62%, var(--palette-green-800) 100%);\n  /* The v1 name for the stage */\n  --gradient-art-green: var(--gradient-stage);\n  /* Inset art inside the feature card; the deep end is green-900 at 30 percent */\n  --gradient-art-on-accent:\n    radial-gradient(90% 70% at 20% 18%, rgba(255, 255, 255, 0.4) 0%, rgba(255, 255, 255, 0) 60%),\n    linear-gradient(160deg, rgba(255, 255, 255, 0.26) 0%, rgba(12, 59, 45, 0.3) 100%);\n  --gradient-panel-soft: linear-gradient(160deg, #f7f8fa 0%, #edeff3 100%);\n  --gradient-art-neutral:\n    radial-gradient(110% 80% at 82% 10%, rgba(255, 255, 255, 0.7) 0%, rgba(255, 255, 255, 0) 62%),\n    linear-gradient(160deg, #eef1f6 0%, #dfe4ec 100%);\n  --pattern-waiting: repeating-linear-gradient(135deg, var(--color-warning-soft) 0 4px, var(--color-warning) 4px 6px);\n\n  /* Glass over gradients, with a 14px backdrop blur. glass-deep is green-900 at 72 percent:\n     white text passes 4.5:1 on it over any backdrop, white included. glass-light passes ink and\n     ink-secondary over any backdrop, black included. */\n  --glass-deep: rgba(12, 59, 45, 0.72);\n  --glass-deep-border: rgba(255, 255, 255, 0.24);\n  --glass-light: rgba(255, 255, 255, 0.88);\n  --glass-light-border: rgba(255, 255, 255, 0.6);\n  --glass-blur: 14px;\n\n  /* Type. next/font sets --font-instrument-sans and --font-ibm-plex-mono on <html>; the\n     fallbacks keep the stack valid when those variables are missing. */\n  --font-sans: var(--font-instrument-sans, \"Instrument Sans\"), ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n  --font-mono: var(--font-ibm-plex-mono, \"IBM Plex Mono\"), ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \"Liberation Mono\", monospace;\n  --font-weight-regular: 400;\n  --font-weight-medium: 500;\n  --font-weight-semibold: 600;\n  --font-weight-bold: 700;\n\n  /* Display and h1 scale with the viewport: the first value is the size at 360 px. */\n  --text-display-xl-size: clamp(2.5rem, 1.5rem + 4.4444vw, 4.75rem);\n  --text-display-xl-leading: 1.02;\n  --text-display-xl-tracking: -0.035em;\n  --text-display-xl-weight: 500;\n  --text-display-l-size: clamp(2rem, 1.4444rem + 2.4691vw, 3.25rem);\n  --text-display-l-leading: 1.06;\n  --text-display-l-tracking: -0.032em;\n  --text-display-l-weight: 500;\n  --text-h1-size: clamp(1.5625rem, 1.2868rem + 1.2255vw, 1.875rem);\n  --text-h1-leading: 1.15;\n  --text-h1-tracking: -0.025em;\n  --text-h1-weight: 600;\n  --text-h2-size: 1.3125rem;\n  --text-h2-leading: 1.25;\n  --text-h2-tracking: -0.014em;\n  --text-h2-weight: 600;\n  --text-h3-size: 1rem;\n  --text-h3-leading: 1.35;\n  --text-h3-tracking: -0.012em;\n  --text-h3-weight: 600;\n  --text-figure-l-size: clamp(2rem, 1.5rem + 2.2222vw, 2.375rem);\n  --text-figure-l-leading: 1.1;\n  --text-figure-l-tracking: -0.03em;\n  --text-figure-l-weight: 600;\n  --text-figure-m-size: 1.75rem;\n  --text-figure-m-leading: 1.15;\n  --text-figure-m-tracking: -0.028em;\n  --text-figure-m-weight: 600;\n  --text-figure-s-size: 1.3125rem;\n  --text-figure-s-leading: 1.2;\n  --text-figure-s-tracking: -0.02em;\n  --text-figure-s-weight: 600;\n  --text-body-l-size: 0.9375rem;\n  --text-body-l-leading: 1.6;\n  --text-body-size: 0.9375rem;\n  --text-body-leading: 1.55;\n  --text-body-s-size: 0.8125rem;\n  --text-body-s-leading: 1.5;\n  --text-label-size: 0.75rem;\n  --text-label-leading: 1.25;\n  --text-label-tracking: 0.005em;\n  --text-micro-size: 0.6875rem;\n  --text-micro-leading: 1.25;\n  --text-micro-tracking: 0.02em;\n  --text-mono-size: 0.8125rem;\n  --text-mono-leading: 1.5;\n  --text-mono-s-size: 0.75rem;\n  --text-mono-s-leading: 1.5;\n  /* 16px keeps iOS Safari from zooming into a focused field. */\n  --text-input-size: 1rem;\n  --text-input-leading: 1.25;\n  --tracking-caps: 0.025em;\n\n  /* Spacing. Names match Tailwind's default keys, so p-4 and var(--space-4) are the same 16px. */\n  --space-0: 0px;\n  --space-px: 1px;\n  --space-0-5: 0.125rem;\n  --space-1: 0.25rem;\n  --space-1-5: 0.375rem;\n  --space-2: 0.5rem;\n  --space-2-5: 0.625rem;\n  --space-3: 0.75rem;\n  --space-3-5: 0.875rem;\n  --space-4: 1rem;\n  --space-5: 1.25rem;\n  --space-6: 1.5rem;\n  --space-7: 1.75rem;\n  --space-8: 2rem;\n  --space-9: 2.25rem;\n  --space-10: 2.5rem;\n  --space-12: 3rem;\n  --space-14: 3.5rem;\n  --space-16: 4rem;\n  --space-20: 5rem;\n  --space-24: 6rem;\n\n  /* Layout. Gutter, section, card padding and topbar step up in the media blocks below. */\n  --layout-gutter: 1rem;\n  --layout-section: 4rem;\n  --layout-stack: 1rem;\n  --layout-card-padding: 1rem;\n  --layout-content: 75rem;\n  --layout-reading: 42.5rem;\n  --layout-form: 53.75rem;\n  --layout-dialog: 30rem;\n  --layout-toast: 25rem;\n  --layout-sheet-max: 90dvh;\n  --layout-rail: 16.375rem;\n  --layout-rail-compact: 14rem;\n  --layout-topbar: 3.875rem;\n  --layout-bottom-nav: 4.25rem;\n\n  --size-touch: 2.75rem;\n  --size-control-sm: 2.5rem;\n  --size-control: 2.75rem;\n  --size-control-lg: 3rem;\n  --size-icon: 1.25rem;\n  --size-icon-tile: 2.625rem;\n  --size-avatar: 2.125rem;\n\n  /* Radii, by role */\n  --radius-xs: 6px;\n  --radius-control: 10px;\n  --radius-row: 14px;\n  --radius-panel: 16px;\n  --radius-module: 18px;\n  --radius-large: 20px;\n  --radius-workspace: 22px;\n  --radius-card: 24px;\n  --radius-sheet: 28px;\n  --radius-pill: 999px;\n\n  /* Shadows. Bounded objects only (a card that is one selectable thing, a floating layer);\n     rows in a list never carry a shadow. */\n  --shadow-soft: 0 1px 3px rgba(11, 11, 12, 0.05);\n  --shadow-card: 0 1px 2px rgba(11, 11, 12, 0.04), 0 6px 18px rgba(11, 11, 12, 0.05);\n  --shadow-raised: 0 1px 2px rgba(11, 11, 12, 0.06), 0 4px 12px rgba(11, 11, 12, 0.05);\n  --shadow-workspace: 0 1px 2px rgba(11, 11, 12, 0.04), 0 8px 24px rgba(11, 11, 12, 0.04);\n  --shadow-floating: 0 12px 40px rgba(11, 11, 12, 0.1);\n  --shadow-overlay: 0 12px 40px rgba(11, 11, 12, 0.16);\n\n  --border-width: 1px;\n  --border-width-strong: 2px;\n  --focus-ring-width: 2px;\n  --focus-ring-offset: 2px;\n  --opacity-disabled: 0.5;\n\n  /* Motion */\n  --duration-fast: 140ms;\n  --duration-standard: 220ms;\n  --duration-narrative: 360ms;\n  --ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);\n  --ease-exit: cubic-bezier(0.4, 0, 1, 1);\n  --motion-distance: 8px;\n  --motion-sheet-offset: 100%;\n\n  --z-sticky: 30;\n  --z-nav: 40;\n  --z-header: 50;\n  --z-overlay: 60;\n  --z-toast: 70;\n}\n\n@media (min-width: 768px) {\n  :root {\n    --layout-gutter: 1.25rem;\n    --layout-section: 6.5rem;\n    --layout-card-padding: 1.25rem;\n    --layout-topbar: 4.25rem;\n    --text-body-l-size: 1.0625rem;\n  }\n}\n\n@media (min-width: 1024px) {\n  :root {\n    --layout-gutter: 1.625rem;\n  }\n}\n\n@media (min-width: 1440px) {\n  :root {\n    --layout-gutter: 2.25rem;\n  }\n}\n\n/* Movement becomes a fade: components translate by these distances, which drop to zero. */\n@media (prefers-reduced-motion: reduce) {\n  :root {\n    --motion-distance: 0px;\n    --motion-sheet-offset: 0%;\n  }\n}\n\n/*\n  Dark theme (D-029), after the owner's dark dashboard reference: a near-black page, cards one step\n  lighter with a hairline, and text that steps down from near white in two greys. The pill turns white\n  with dark text, as the reference's selected pill does. Green stays the accent: fills move to green-500,\n  which still carries white text and reads on black, and green words, links and the focus ring use the\n  mint green-300, which sits above the skipped band. Apricot keeps the spend side, one step lighter.\n  Tokens left out here follow the semantic token they point at (equity follows accent, waiting follows\n  warning); contrast.mjs lists them and fails a token that has no dark value. docs/DESIGN.md \"Dark theme\".\n*/\n:root[data-theme='dark'] {\n  color-scheme: dark;\n\n  /* Surfaces: page, cards, inner panels, chips. The shell behind the rail is darkest; the workspace\n     panel is the page color, so cards stand one step above it. */\n  --color-canvas: #0b0b0d;\n  --color-surface: #131316;\n  --color-surface-muted: #1a1a1e;\n  --color-surface-strong: #242429;\n  --color-shell: #060607;\n  --color-shell-raised: rgba(255, 255, 255, 0.055);\n  --color-chrome: rgba(11, 11, 12, 0.9);\n  --color-scrim: rgba(11, 11, 12, 0.72);\n  --color-selection: var(--palette-green-800);\n\n  --color-border: #232328;\n  --color-border-strong: #313137;\n  --color-border-control: #75757e;\n\n  --color-ink: #f4f4f5;\n  --color-ink-secondary: #b4b4bb;\n  --color-ink-muted: #8f8f98;\n  --color-ink-inverse: #0b0b0c;\n\n  --color-brand: #f4f4f5;\n  --color-brand-strong: #ffffff;\n  --color-on-brand: #0b0b0c;\n\n  --color-accent: var(--palette-green-500);\n  --color-accent-strong: var(--palette-green-600);\n  --color-accent-soft: var(--palette-green-950);\n  --color-accent-border: var(--palette-green-800);\n  --color-accent-text: var(--palette-green-300);\n\n  --color-link: var(--palette-green-300);\n  --color-link-hover: var(--palette-green-200);\n  /* The ring sits outside the white pill; rings drawn inset on the pill use focus-inverse. */\n  --color-focus: var(--palette-green-300);\n  --color-focus-inverse: #0b0b0c;\n\n  --color-spend: var(--palette-apricot-400);\n  --color-spend-soft: #2e1d10;\n  --color-spend-surface: #1c140e;\n  --color-spend-border: #5c3514;\n  --color-spend-text: var(--palette-apricot-300);\n  --color-equity-surface: #0a1d17;\n  --color-equity-border: var(--palette-green-800);\n\n  --color-success: var(--palette-green-500);\n  --color-success-soft: var(--palette-green-950);\n  --color-success-text: var(--palette-green-300);\n  --color-warning: #e3ad3c;\n  --color-warning-soft: #2a2111;\n  --color-warning-text: #f1c873;\n  --color-danger: #d93b3b;\n  --color-danger-strong: #c42c30;\n  --color-danger-soft: #2d1415;\n  --color-danger-text: #ff8f8a;\n  --color-info: var(--palette-green-500);\n  --color-info-soft: #0a1d17;\n  --color-info-text: var(--palette-green-300);\n\n  /* green-500 at 22 percent */\n  --color-chart-area: rgba(0, 133, 97, 0.22);\n\n  --gradient-hero: linear-gradient(155deg, var(--palette-green-950) 0%, var(--palette-green-900) 100%);\n  --gradient-apricot: linear-gradient(155deg, #1c140e 0%, #2e1d10 55%, #3d2613 100%);\n  /* The glow is green-500 */\n  --gradient-stage:\n    radial-gradient(120% 90% at 18% 12%, rgba(255, 255, 255, 0.07) 0%, rgba(255, 255, 255, 0) 60%),\n    radial-gradient(110% 85% at 96% 100%, rgba(0, 133, 97, 0.55) 0%, rgba(0, 133, 97, 0.22) 30%, rgba(0, 133, 97, 0) 68%),\n    linear-gradient(158deg, var(--palette-green-950) 0%, #0b1a15 42%, #0b0b0d 100%);\n  --gradient-step:\n    radial-gradient(90% 55% at 20% 0%, rgba(255, 255, 255, 0.08) 0%, rgba(255, 255, 255, 0) 62%),\n    linear-gradient(175deg, var(--palette-green-900) 0%, var(--palette-green-800) 28%, var(--palette-green-600) 62%, var(--palette-green-950) 100%);\n  --gradient-panel-soft: linear-gradient(160deg, #1a1a1e 0%, #131316 100%);\n  --gradient-art-neutral:\n    radial-gradient(110% 80% at 82% 10%, rgba(255, 255, 255, 0.06) 0%, rgba(255, 255, 255, 0) 62%),\n    linear-gradient(160deg, #1d1d22 0%, #141417 100%);\n\n  /* Light glass becomes dark glass: ink at 82 percent carries near-white text over a white backdrop. */\n  --glass-light: rgba(11, 11, 12, 0.82);\n  --glass-light-border: rgba(255, 255, 255, 0.1);\n\n  /* Shadows barely read on black, so the workspace and raised rows get a hairline ring instead. */\n  --shadow-soft: 0 1px 2px rgba(11, 11, 12, 0.6);\n  --shadow-card: 0 1px 2px rgba(11, 11, 12, 0.6), 0 8px 24px rgba(11, 11, 12, 0.45);\n  --shadow-raised: 0 0 0 1px rgba(255, 255, 255, 0.06), 0 2px 8px rgba(11, 11, 12, 0.6);\n  --shadow-workspace: 0 0 0 1px rgba(255, 255, 255, 0.06);\n  --shadow-floating: 0 16px 48px rgba(11, 11, 12, 0.6);\n  --shadow-overlay: 0 16px 48px rgba(11, 11, 12, 0.72);\n}\n\n/* Glass needs a solid fallback where the platform cannot blur or the viewer asks for less\n   transparency; both values keep the same text pairs passing. */\n@media (prefers-reduced-transparency: reduce) {\n  :root {\n    --glass-deep: var(--palette-green-900);\n    --glass-light: #ffffff;\n  }\n\n  :root[data-theme='dark'] {\n    --glass-light: #1a1a1e;\n  }\n}\n";
